import "server-only";
import { createClient } from "@sanity/client";

if (!process.env.NEXT_PUBLIC_SANITY_PROJECT_ID) {
  throw new Error("NEXT_PUBLIC_SANITY_PROJECT_ID is missing from .env.local");
}

export const sanityClient = createClient({
  projectId: process.env.NEXT_PUBLIC_SANITY_PROJECT_ID,
  dataset: process.env.NEXT_PUBLIC_SANITY_DATASET ?? "production",
  // Bump this date when you need access to newer Sanity API features.
  apiVersion: "2024-01-01",
  // useCdn: false keeps data fresh on the server. The CDN is for
  // client-side reads where staleness is acceptable.
  useCdn: false,
  // Optional — read-public datasets work without a token.
  token: process.env.SANITY_API_TOKEN,
});

files.queries.ts:
"use server";

import { sanityClient } from "./client";

/**
 * Run any GROQ query against your Sanity dataset.
 *
 * Tag fetch results for ISR cache invalidation:
 *   query(groq, params, { next: { tags: ["article"] } })
 *
 * Then call revalidateTag("article") from your webhook handler to bust the cache.
 */
export async function query<T>(
  groqQuery: string,
  params?: Record<string, unknown>,
  options?: Parameters<typeof sanityClient.fetch>[2],
): Promise<T> {
  return sanityClient.fetch<T>(groqQuery, params ?? {}, options);
}

/**
 * Fetch all published documents of a given type, ordered by `_updatedAt` descending.
 * Drafts (IDs prefixed with `drafts.`) are excluded automatically.
 */
export async function getDocumentsByType<T>(
  type: string,
  options?: { limit?: number; order?: string },
): Promise<T[]> {
  const order = options?.order ?? "_updatedAt desc";
  const limit = options?.limit !== undefined ? `[0...${options.limit}]` : "";
  return query<T[]>(
    `*[_type == $type && !(_id in path("drafts.**"))] | order(${order})${limit}`,
    { type },
    { next: { tags: [type] } },
  );
}

/** Fetch a single document by its `_id`. Works for both drafts and published documents. */
export async function getDocumentById<T>(id: string): Promise<T | null> {
  return query<T | null>(`*[_id == $id][0]`, { id });
}

/**
 * Fetch a single published document by content type and `slug.current` value.
 * This is the most common Next.js CMS pattern — use it with `generateStaticParams`.
 *
 * Assumes your content type has a `slug` field of type `slug` in Sanity Studio.
 */
export async function getBySlug<T>(
  type: string,
  slug: string,
): Promise<T | null> {
  return query<T | null>(
    `*[_type == $type && slug.current == $slug && !(_id in path("drafts.**"))][0]`,
    { type, slug },
    { next: { tags: [type] } },
  );
}

files.webhooks.ts:
import crypto from "crypto";
import { revalidateTag, revalidatePath } from "next/cache";

export interface SanityWebhookPayload {
  /** Content type name, e.g. "article", "product" */
  _type: string;
  /** Document ID — prefixed with "drafts." for unpublished documents */
  _id: string;
  _rev?: string;
  _updatedAt?: string;
  [key: string]: unknown;
}

// Reject webhooks older than 5 minutes — guards against replay attacks.
const SIGNATURE_TOLERANCE_MS = 5 * 60 * 1000;

/**
 * Verifies the Sanity webhook signature.
 *
 * Header format: `t=<unix_timestamp>,v1=<base64url_hmac_sha256>`
 * Signed data:   `<timestamp>.<raw_body>`
 *
 * Note: Sanity encodes the HMAC as base64url (not hex like Stripe/Calendly).
 */
export function verifyWebhookSignature(
  body: string,
  signatureHeader: string,
  secret: string,
): boolean {
  const parts: Record<string, string> = {};
  for (const part of signatureHeader.split(",")) {
    // Require exactly one `=` per part. base64url has no `=` padding,
    // so a malformed header like `t=1=garbage` is always invalid.
    const [key, value, ...extra] = part.split("=");
    if (!key || value === undefined || extra.length > 0) return false;
    parts[key] = value;
  }

  const timestamp = parts["t"];
  const signature = parts["v1"];
  if (!timestamp || !signature) return false;

  const eventTimeMs = parseInt(timestamp, 10) * 1000;
  if (Math.abs(Date.now() - eventTimeMs) > SIGNATURE_TOLERANCE_MS) return false;

  const expected = crypto
    .createHmac("sha256", secret)
    .update(`${timestamp}.${body}`)
    .digest("base64url");

  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(signature, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

export async function handleSanityEvent(
  payload: SanityWebhookPayload,
): Promise<void> {
  // Draft-only mutations (e.g. auto-saves while editing) should not bust the
  // published content cache. Only revalidate when a document is published.
  if (payload._id.startsWith("drafts.")) {
    console.log(
      `[sanity] Skipping revalidation for draft document: ${payload._id}`,
    );
    return;
  }

  revalidateTag(payload._type);
  // TODO: Narrow this to specific paths rather than a full-layout revalidation —
  // e.g. revalidatePath(`/${payload._type}`) or per-slug if your payload includes one.
  revalidatePath("/", "layout");
  console.log(
    `[sanity] Revalidated tag "${payload._type}" and path "/" for document ${payload._id}`,
  );
}

files.route.ts:
import { headers } from "next/headers";
import {
  handleSanityEvent,
  verifyWebhookSignature,
} from "@/infra/sanity/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signatureHeader = headersList.get("sanity-webhook-signature");

  if (!signatureHeader) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.SANITY_WEBHOOK_SECRET) {
    console.error("[sanity webhook] SANITY_WEBHOOK_SECRET is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (
    !verifyWebhookSignature(
      body,
      signatureHeader,
      process.env.SANITY_WEBHOOK_SECRET,
    )
  ) {
    console.error("[sanity webhook] Invalid signature");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[sanity webhook] Malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Sanity retries — distinct from 4xx above.
  try {
    await handleSanityEvent(event);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[sanity webhook] Handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
